		m_maxLength = 0.0f;
		m_spacing = 0.0f;
		m_pulseRate = 0.0f;
		m_maxHeight = -1;
		zrdr_findint(reader, "MAXHEIGHT", &m_maxHeight, 1);
		zrdr_findreal(reader, "PULSERATE", &m_pulseRate, 1);
		zrdr_findreal(reader, "SPACING", &m_spacing, 1);
