	f32 m_maxLength;  /* +0x28 MAXLENGTH: line width before a word wraps */
	f32 m_spacing;    /* +0x2c SPACING: line height */
	f32 m_pulseRate;  /* +0x30 PULSERATE: cursor pulse rate */
